import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CmvPqeTF.js";const p=JSON.parse('{"title":"开发文档总览","description":"","frontmatter":{},"headers":[],"relativePath":"dev/index.md","filePath":"dev/index.md","lastUpdated":1788361893000}'),r={name:"dev/index.md"};function l(i,e,c,n,s,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="开发文档总览" tabindex="-1">开发文档总览 <a class="header-anchor" href="#开发文档总览" aria-label="Permalink to &quot;开发文档总览&quot;">​</a></h1><p>面向参与 vShell 开发的读者：整体架构、关键数据流与存储设计。使用类文档见<a href="./../guide/">使用指南</a>。</p><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to &quot;文档索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./architecture.html">架构总览</a></td><td>Wails 3 前后端分层、服务绑定与事件通信全景、目录结构</td></tr><tr><td><a href="./terminal-io.html">终端 I/O 数据流</a></td><td>终端输入 / 输出 / 调整大小的事件链路与缓冲机制</td></tr><tr><td><a href="./storage-crypto.html">数据存储与加密</a></td><td>SQLite 表结构、迁移机制、AES-256-GCM 凭证加密</td></tr><tr><td><a href="./development.html">构建与开发环境</a></td><td>工具链、Taskfile 任务、pnpm 项目隔离、文档站部署</td></tr></tbody></table><h2 id="核心约束-开发红线" tabindex="-1">核心约束（开发红线） <a class="header-anchor" href="#核心约束-开发红线" aria-label="Permalink to &quot;核心约束（开发红线）&quot;">​</a></h2><ol><li><strong>终端数据走 Wails Events</strong>，绝不使用同步 <code>Call/Bind</code>（会阻塞每字节的 I/O）</li><li><strong>敏感数据加密</strong>：密码、私钥、口令必须 AES-256-GCM 加密后入库，禁止明文</li><li><strong>UI 一律 Naive UI</strong>：禁止浏览器原生 <code>alert/confirm</code>，禁止混用其他 UI 库</li><li><strong>PTY 规范</strong>：SSH 会话必须 <code>RequestPty(&quot;xterm-256color&quot;, ...)</code> + <code>Shell()</code>，不得用 exec 模拟交互终端</li><li><strong>纯本地</strong>：无任何服务端代码、云同步、注册登录</li><li><strong>无 CGO</strong>：SQLite 用 <code>modernc.org/sqlite</code>（纯 Go），不用 <code>mattn/go-sqlite3</code></li></ol><h2 id="开发流程约定" tabindex="-1">开发流程约定 <a class="header-anchor" href="#开发流程约定" aria-label="Permalink to &quot;开发流程约定&quot;">​</a></h2><ul><li>问题登记：<code>docs/issues/</code>，编号四位零填充递增，模板见 <code>_TEMPLATE.md</code>（该目录不发布到文档站）</li><li>提交信息：中文描述，<code>fix:</code> / <code>feat:</code> 前缀</li><li>前端改动需通过 <code>pnpm typecheck</code>，后端改动需通过 <code>go build ./... &amp;&amp; go vet ./...</code></li></ul>',8)])])}const u=t(r,[["render",l]]);export{p as __pageData,u as default};
